export default function Page1(){return <><Frame0 /><div className={"scroll-progress"} data-scroll-progress={"#pf2-article-body"} aria-hidden={"true"}></div><main><section id={"pf2-article-head"} className={"custom-section pt-[clamp(2rem,1rem_+_3vw,3.5rem)]"} aria-labelledby={"pf2-article-title"}><div className={"container"}><nav className={"custom-label custom-ph-crumb mb-[clamp(2rem,1.25rem_+_2.5vw,3.5rem)]"} aria-label={"Breadcrumb"} data-anim={"fade-up"}><a href={"#page=demo-creative-studio-1"}>{"Framo Studio"}</a>{" — "}<a href={"#page=demo-creative-studio-1-blog"}>{"Blog"}</a>{" — "}<span aria-current={"page"}>{"Process"}</span></nav><h1 id={"pf2-article-title"} className={"max-w-[13em] text-[clamp(3rem,1.9rem_+_4.6vw,6.5rem)] font-medium leading-[0.98] tracking-[-0.045em] text-balance"} data-anim={"fade-up"} data-anim-duration={"1300"}>{"Designing wayfinding for the dark"}</h1><div className={"grid gap-10 mt-[clamp(2rem,1.25rem_+_2.5vw,3.5rem)] lg:gap-x-[clamp(3rem,6vw,7rem)] lg:grid-cols-[minmax(0,7fr)_minmax(0,5fr)] lg:[align-items:end]"}><p className={"max-w-152 text-[clamp(1.25rem,1.1rem_+_0.5vw,1.5rem)] leading-[1.45] tracking-[-0.015em] text-text text-pretty"} data-anim={"fade-up"} data-anim-delay={"120"}>{"Aurora Labs does its best work after the lights go down. Here’s how we built 140 signs that visitors can read in a dark hall without breaking its spell."}</p><dl className={"grid grid-cols-2 gap-y-5 gap-x-8 pt-6 border-t border-t-(--custom-line)"} data-anim={"fade-up"} data-anim-delay={"200"}><div className={"grid gap-1 col-span-full"}><dt className={"sr-only"}>{"Written By"}</dt><dd className={"text-[0.9375rem] font-normal text-soft flex items-center gap-3.5 leading-[1.4]"}><img className={"flex-none size-12 rounded-pill object-cover"} src={"https://draftmango.com/framo/assets/media/placeholder/160x160.svg"} alt={""} width={"96"} height={"96"} decoding={"async"} /><span><strong className={"block text-[1.0625rem] font-semibold text-text"}>{"Lotte Wouters"}</strong>{" Senior Brand Designer"}</span></dd></div><div className={"grid gap-1"}><dt className={"custom-label"}>{"Published"}</dt><dd className={"text-[1.0625rem] font-medium text-text"}><time datetime={"2026-10-06"}>{"Oct 6, 2026"}</time></dd></div><div className={"grid gap-1"}><dt className={"custom-label"}>{"Reading Time"}</dt><dd className={"text-[1.0625rem] font-medium text-text"}>{"7 minutes"}</dd></div></dl></div></div></section><section id={"pf2-article-cover"} className={"custom-section"} aria-label={"Cover"}><div className={"container"}><figure className={"grid gap-4"} data-anim={"fade-up"} data-anim-delay={"250"}><img className={"w-full aspect-[3/2] object-cover rounded-(--custom-radius) md:aspect-video"} src={"https://draftmango.com/framo/assets/media/placeholder/2880x1620.svg"} alt={"A slim wayfinding column glowing cobalt at its edges in a dark museum hall"} width={"2880"} height={"1620"} fetchPriority={"high"} decoding={"async"} /><figcaption className={"text-[0.9375rem] leading-[1.45] text-soft"}>{"The Moon Hall at Aurora Labs, Ghent, an hour after the house lights dropped."}</figcaption></figure></div></section><section id={"pf2-article-body"} className={"custom-section"} aria-labelledby={"pf2-article-title"}><div className={"container grid grid-cols-1 gap-y-[clamp(3rem,2rem_+_3vw,4.5rem)] lg:grid-cols-[minmax(12rem,1fr)_minmax(0,42rem)_minmax(0,1fr)] lg:gap-x-[clamp(2.5rem,4vw,4rem)] lg:[align-items:start]"}><aside className={"hidden lg:grid lg:sticky lg:top-10 lg:gap-4 lg:row-[1_/_span_2]"} aria-label={"In this post"}><p className={"custom-label"}>{"In This Post"}</p><ol className={"custom-article-toc grid gap-2.5"} role={"list"}><li><a href={"#pf2-art-room"}>{"Start in the room"}</a></li><li><a href={"#pf2-art-edge"}>{"Light the edge, not the face"}</a></li><li><a href={"#pf2-art-type"}>{"One typeface, 140 signs"}</a></li><li><a href={"#pf2-art-motion"}>{"Motion that waits for you"}</a></li><li><a href={"#pf2-art-keep"}>{"What we’d keep"}</a></li></ol></aside><div className={"article-body article-body--flush custom-article-body max-w-168 text-[clamp(1.125rem,1.08rem_+_0.2vw,1.1875rem)] leading-[1.7] lg:col-[2]"}><p>{"Most wayfinding is designed in daylight, on a white table, for a building with the lights on. Aurora Labs, a science centre in Ghent, is at its busiest after eight in the evening, when the halls are dim on purpose. Planetarium shows, light installations and night lectures all need the dark. A bright sign is not neutral there; it’s a hole in the exhibit."}</p><p>{"So the brief Sofie Lambrecht gave us came with an odd constraint: visitors had to find their way without noticing the signs. Over fourteen weeks we designed the identity, the wayfinding and the motion around one idea. "}<strong>{"A sign should be the quietest thing in the room until you need it."}</strong></p><h2 id={"pf2-art-room"}>{"Start in the room, not on the screen"}</h2><p className={"mt-4"}>{"We spent the first two weeks in the building, mostly at night. We walked every route from the entrance to the Moon Hall with the house lights at show level, and we timed how long our eyes took to adjust after leaving the bright café. The answer was about forty seconds, and for those forty seconds most of what we had pinned on the studio wall was unreadable."}</p><p>{"That changed the order of the work. Before we drew a single arrow, we wrote down three numbers for every sign position: how dark the room is, how far away people stand, and how long they have to read while walking."}</p><p>{"It also gave us a vocabulary. “Café distance”, “corridor speed” and “show dark” became the three columns of a spreadsheet that drove every decision after that, from the size of a letter to the brightness of an LED strip."}</p><h2 id={"pf2-art-edge"}>{"Light the edge, not the face"}</h2><p className={"mt-4"}>{"Our first prototypes were backlit panels, and they failed in a useful way. A glowing rectangle in a dark hall pulls every eye towards it and flattens the exhibit behind it. So we tried the opposite: matte, dark faces with the letters cut through and lit from the edge. From a distance the column almost disappears; up close, the words glow just enough to read."}</p><figure className={"custom-article-figure my-12"}><span className={"custom-select custom-select--latent block custom-article-figure-frame -m-2 p-2"}><img className={"w-full aspect-[3/2] object-cover rounded-(--custom-radius-card)"} src={"https://draftmango.com/framo/assets/media/placeholder/1600x1067.svg"} alt={"White sign prototypes with cut arrows and cobalt type samples spread across a wooden workbench"} width={"1600"} height={"1067"} loading={"lazy"} decoding={"async"} /><span className={"custom-select-tag"} aria-hidden={"true"}>{"Prototype 31"}</span></span><figcaption className={"text-start text-soft"}>{"Prototype faces on the workbench. We cut thirty-one of them before the edge light felt right."}</figcaption></figure><p>{"We tested each one on site, with a light meter and, more usefully, with visitors. We asked people to find the lecture theatre, said nothing else, and watched where they slowed down. Every hesitation went on the wall as a note, and most of the notes were about contrast, not about arrows."}</p><blockquote className={"custom-article-pull my-12 pl-0 border-0"}><p className={"font-heading text-[clamp(1.625rem,1.3rem_+_1.2vw,2.375rem)] font-normal leading-[1.18] tracking-[-0.03em] text-text text-pretty"}>{"“A sign in a dark hall is never neutral. "}<span className={"custom-key"}>{"Either it belongs to the room, or it’s a hole in it.”"}</span></p></blockquote><h2 id={"pf2-art-type"}>{"One typeface, 140 signs"}</h2><p className={"mt-4"}>{"Low light is unkind to type. Thin strokes vanish, tight counters fill in, and small details turn to noise. We drew a wayfinding cut of the identity’s typeface with wider letters, open counters and slightly heavier hairlines, and used it for every one of the 140 signs, from the car park to the planetarium door."}</p><p>{"Keeping to one face did more than keep the system tidy. Visitors learned its shapes in the first room and read it faster in every room after. The same letters run through the identity, the tickets and the evening programme, so the building and the brand speak with one voice. The rules we kept were written on the studio wall for the whole project:"}</p><ul><li><strong>{"Dark at rest."}</strong>{" Signs are lit at the edge, never glowing on their face."}</li><li><strong>{"Nothing under 40 mm."}</strong>{" The cap height we could still read at six metres in show light."}</li><li><strong>{"One baseline."}</strong>{" Arrows and words share it, so a single glance gives both."}</li><li><strong>{"Colour marks the zone, never the way."}</strong>{" You find the route by shape; the colour confirms where you are."}</li></ul><h2 id={"pf2-art-motion"}>{"Motion that waits for you"}</h2><p className={"mt-4"}>{"Some routes change during an evening: the Signal Corridor closes for a show, and the Night Lectures move between halls. Noor and Bram built a small set of digital signs that animate only when the plan changes, then settle back into stillness. Nothing on them loops, and nothing moves to catch your eye when there’s no news."}</p><p>{"We set the speed of every transition to the pace of someone walking, not the pace of a screen. A change of route fades in over two seconds and holds for as long as the change lasts. Test visitors called the signs calm, and a few didn’t remember seeing any animation at all, which is exactly what we were after."}</p><h2 id={"pf2-art-keep"}>{"What we’d keep"}</h2><p className={"mt-4"}>{"The building reopened in March. In the first season evening visitors rose by 61%, and the team hasn’t added a single sign since opening day. That’s the number we’re proudest of, because extra signs are what a building collects when its wayfinding doesn’t work."}</p><p>{"We’d also keep the habit of testing at full size. Every Thursday review that season happened in the building, in the dark, in front of the real sign, and nothing went to production until someone who had never seen it had read it there."}</p><p>{"If you design for the dark, start there too. Go at night, take a light meter, time your own eyes, and let every sign be the quietest thing in the room until somebody needs it. The whole project is on the "}<a href={"#page=demo-creative-studio-1-project"}>{"Aurora Labs case study"}</a>{"."}</p></div><div className={"grid gap-8 lg:col-[2]"}><div className={"social-share custom-article-share justify-between gap-4 py-5"}><span className={"custom-label"}>{"Share This Post"}</span><ul className={"social-list gap-2"} role={"list"}><li><button type={"button"} className={"btn btn-circle btn-copy"} data-copy-url={""} data-copy-done={"Link copied"} aria-label={"Copy the link to this post"}><i className={"ph ph-link"} aria-hidden={"true"}></i><span className={"sr-only"} data-copy-label={""} aria-live={"polite"}></span></button></li><li><a href={"#"} className={"social-link social-link--circle social-link--soft"} aria-label={"Share on LinkedIn"}><i className={"ph ph-linkedin-logo"} aria-hidden={"true"}></i></a></li><li><a href={"#"} className={"social-link social-link--circle social-link--soft"} aria-label={"Share on X"}><i className={"ph ph-x-logo"} aria-hidden={"true"}></i></a></li><li><a href={"mailto:?subject=Designing%20wayfinding%20for%20the%20dark"} className={"social-link social-link--circle social-link--soft"} aria-label={"Share by email"}><i className={"ph ph-envelope-simple"} aria-hidden={"true"}></i></a></li></ul></div><aside className={"custom-article-bio grid grid-cols-1 gap-y-5 gap-x-7 p-[clamp(1.5rem,1rem_+_2vw,2.5rem)] rounded-(--custom-radius) text-text sm:grid-cols-[auto_minmax(0,1fr)]"} aria-label={"About the author"}><img className={"size-20 rounded-pill object-cover"} src={"https://draftmango.com/framo/assets/media/placeholder/800x800.svg"} alt={""} width={"400"} height={"400"} loading={"lazy"} decoding={"async"} /><div className={"grid gap-1.5 justify-items-start"}><p className={"custom-label"}>{"Written By"}</p><p className={"text-[clamp(1.375rem,1.25rem_+_0.4vw,1.625rem)] font-semibold leading-[1.2] tracking-[-0.02em]"}>{"Lotte Wouters"}</p><p className={"custom-article-bio-text text-[1.0625rem] leading-[1.6] text-pretty"}>{"Senior Brand Designer at Framo, and the lead on Aurora Labs’ identity and signs. Before Antwerp she spent five years drawing signs for hospitals and train stations, which is why she still checks every arrow twice."}</p><a className={"btn btn-lg btn-link btn-link-dark btn-link-arrow mt-2"} href={"#page=demo-creative-studio-1-studio"}><span className={"link-arrow"} aria-hidden={"true"}></span>{"Meet the Studio"}</a></div></aside></div></div></section><section id={"pf2-article-related"} className={"custom-section"} aria-labelledby={"pf2-article-related-title"}><div className={"container"}><div className={"custom-head custom-head--row"}><h2 id={"pf2-article-related-title"} className={"custom-title"} data-anim={"fade-up"}>{"Keep reading"}</h2><a href={"#page=demo-creative-studio-1-blog"} className={"btn btn-lg btn-link btn-link-dark btn-link-arrow"} data-anim={"fade-up"}><span className={"link-arrow"} aria-hidden={"true"}></span>{"All Posts"}</a></div><ul className={"custom-blog-grid"} role={"list"} data-anim-stagger={"90"}><li data-anim={"fade-up"}><a className={"custom-blog-card custom-select-trigger grid gap-2.5 text-text"} href={"#page=demo-creative-studio-1-article"}><span className={"custom-select custom-select--latent block custom-blog-frame"}><img src={"https://draftmango.com/framo/assets/media/placeholder/1800x1200.svg"} alt={""} width={"1800"} height={"1200"} loading={"lazy"} decoding={"async"} /><span className={"custom-select-tag"} aria-hidden={"true"}>{"Open Post"}</span></span><span className={"custom-blog-meta"}>{"Motion "}<span aria-hidden={"true"}>{"·"}</span><time datetime={"2026-09-22"}>{"Sep 22, 2026"}</time><